create table public.student_insights(student_id uuid primary key,school_id uuid not null,source_version bigint not null default 1,status text not null default 'updating',evidence jsonb,content jsonb,model text,prompt_version text,correction text,suppressed boolean not null default false,updated_at timestamptz not null default now(),foreign key(school_id,student_id) references student_registry(school_id,student_id));
create table private.insight_revisions(id bigint generated always as identity primary key,student_id uuid not null,source_version bigint not null,snapshot jsonb not null,created_at timestamptz not null default now());
create table public.teacher_feedback(id uuid primary key default gen_random_uuid(),school_id uuid not null,student_id uuid not null,teacher_id uuid not null,class_id uuid not null,subject text not null,body text not null,created_at timestamptz not null default now(),foreign key(school_id,student_id) references student_registry(school_id,student_id),foreign key(school_id,class_id) references classes(school_id,id));
create table private.support_notes(id uuid primary key default gen_random_uuid(),school_id uuid not null,student_id uuid not null,teacher_id uuid not null,body text not null,created_at timestamptz not null default now());
create table public.report_exports(id uuid primary key default gen_random_uuid(),school_id uuid not null references schools(id),actor_id uuid not null,filters jsonb not null,source_version bigint not null,object_key text,status text not null default 'pending',created_at timestamptz not null default now(),expires_at timestamptz not null default now()+interval '24 hours');
create table public.teacher_profiles(id uuid primary key default gen_random_uuid(),school_id uuid not null,teacher_id uuid not null unique,display_name text not null,designation text not null default '',subjects text[] not null default '{}',classes text[] not null default '{}',approved_fields jsonb not null default '{}',visible boolean not null default false,audience text not null default 'school' check(audience in ('school','public')),revision int not null default 1,published_at timestamptz,unique(school_id,id),foreign key(school_id,teacher_id) references memberships(school_id,id));
create index teacher_search on teacher_profiles using gin(to_tsvector('simple',display_name||' '||designation));
create table public.profile_revisions(id uuid primary key default gen_random_uuid(),school_id uuid not null,profile_id uuid not null,author_id uuid not null,content jsonb not null,state text not null default 'draft' check(state in ('draft','submitted','changes_requested','approved')),created_at timestamptz not null default now(),foreign key(school_id,profile_id) references teacher_profiles(school_id,id));
create table public.professional_updates(id uuid primary key default gen_random_uuid(),school_id uuid not null,profile_id uuid not null,title text not null,kind text not null check(kind in ('workshop','certification','project','resource')),date date not null,evidence_reference text,approved boolean not null default false,foreign key(school_id,profile_id) references teacher_profiles(school_id,id));
create table public.teacher_articles(id uuid primary key default gen_random_uuid(),school_id uuid not null,author_id uuid not null,profile_id uuid not null,published_revision uuid,audience text not null default 'school' check(audience in ('school','public')),published_at timestamptz,archived boolean not null default false,revision int not null default 1,unique(school_id,id),foreign key(school_id,profile_id) references teacher_profiles(school_id,id));
create table public.article_revisions(id uuid primary key default gen_random_uuid(),school_id uuid not null,article_id uuid not null,editor_id uuid not null,title text not null,summary text not null,subject text not null,body text not null,state text not null default 'draft' check(state in ('draft','submitted','changes_requested','approved')),created_at timestamptz not null default now(),foreign key(school_id,article_id) references teacher_articles(school_id,id));
alter table teacher_articles add foreign key(published_revision) references article_revisions(id);
create table public.content_publications(id uuid primary key default gen_random_uuid(),school_id uuid not null,article_id uuid,profile_id uuid,audience text not null,revoked_at timestamptz,cache_version int not null default 1,check(num_nonnulls(article_id,profile_id)=1),foreign key(school_id,article_id) references teacher_articles(school_id,id),foreign key(school_id,profile_id) references teacher_profiles(school_id,id));
create table public.public_assets(id uuid primary key default gen_random_uuid(),school_id uuid not null,publication_id uuid not null references content_publications(id),object_key text not null unique,approved boolean not null default false,revoked_at timestamptz);
create table private.support_sessions(id uuid primary key default gen_random_uuid(),school_id uuid not null,actor_id uuid not null,student_id uuid not null,reason text not null,expires_at timestamptz not null,ended_at timestamptz,check(expires_at<=now()+interval '15 minutes'));
create function private.invalidate_insight() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.student_insights(student_id,school_id)values(new.student_id,new.school_id)on conflict(student_id)do update set source_version=student_insights.source_version+1,status='updating',content=null,updated_at=now();return new;end$$;
create trigger result_invalidation after insert or update on results for each row execute function private.invalidate_insight();
create function private.profile_visible(pid uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.teacher_profiles p join public.memberships m on m.id=p.teacher_id join public.schools s on s.id=p.school_id where p.id=pid and p.visible and m.active and s.status='active' and not private.active_attempt() and ((private.school()=p.school_id and private.role() is not null)or(p.audience='public' and s.public_enabled)))$$;
create function private.report_result(vid uuid,student uuid) returns boolean language sql stable security definer set search_path='' as $$select not private.active_attempt() and (student=auth.uid() and private.role()='student' or private.role()='administrator' and exists(select 1 from public.exam_versions where id=vid and school_id=private.school()) or private.role()='teacher' and exists(select 1 from public.exam_versions e join public.enrollments en on en.class_id=e.class_id where e.id=vid and en.student_id=student and private.assigned(e.class_id,e.subject)))$$;
create function public.write_article(p jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare s uuid:=private.school();a public.teacher_articles;prof public.teacher_profiles;rid uuid;begin perform private.require_access(s,true);select * into prof from public.teacher_profiles where id=(p->>'profileId')::uuid and school_id=s;if private.role()<>'teacher' or prof.teacher_id<>auth.uid() then raise exception 'FORBIDDEN' using errcode='42501';end if;if p->>'articleId' is null then insert into public.teacher_articles(school_id,author_id,profile_id)values(s,auth.uid(),prof.id)returning * into a;else select * into a from public.teacher_articles where id=(p->>'articleId')::uuid for update;if a.author_id<>auth.uid()or a.school_id<>s or a.revision<>(p->>'revision')::int then raise exception 'STALE_REVISION';end if;update public.teacher_articles set revision=revision+1 where id=a.id;end if;if p->>'state' not in ('draft','submitted') then raise exception 'INVALID_STATE';end if;insert into public.article_revisions(school_id,article_id,editor_id,title,summary,subject,body,state)values(s,a.id,auth.uid(),p->>'title',p->>'summary',p->>'subject',p->>'body',p->>'state')returning id into rid;perform private.audit(s,'article.revised',a.id);return rid;end$$;
create function public.moderate_article(p jsonb) returns void language plpgsql security definer set search_path='' as $$declare a public.teacher_articles;r public.article_revisions;s uuid:=private.school();begin perform private.require_access(s);if private.role()<>'administrator' then raise exception 'FORBIDDEN' using errcode='42501';end if;select * into a from public.teacher_articles where id=(p->>'articleId')::uuid and school_id=s for update;if not found then raise exception 'FORBIDDEN' using errcode='42501';end if;if p->>'action'='publish' then select * into r from public.article_revisions where id=(p->>'revisionId')::uuid and article_id=a.id and state='submitted';if not found then raise exception 'INVALID_REVISION';end if;if p->>'audience'='public' and not exists(select 1 from public.schools where id=s and public_enabled)then raise exception 'PUBLIC_NOT_ENABLED';end if;update public.article_revisions set state='approved' where id=r.id;update public.teacher_articles set published_revision=r.id,audience=p->>'audience',published_at=now(),archived=false,revision=revision+1 where id=a.id;insert into public.content_publications(school_id,article_id,audience)values(s,a.id,p->>'audience');elsif p->>'action'='unpublish' then update public.teacher_articles set published_revision=null,published_at=null,revision=revision+1 where id=a.id;update public.content_publications set revoked_at=now(),cache_version=cache_version+1 where article_id=a.id and revoked_at is null;update public.public_assets set revoked_at=now()where publication_id in(select id from public.content_publications where article_id=a.id);else update public.article_revisions set state='changes_requested' where id=(p->>'revisionId')::uuid and article_id=a.id;end if;perform private.audit(s,'article.moderated',a.id,p->>'reason');end$$;
-- Audience-specific projections; no private statistics are stored on public profiles.
create function public.directory(p jsonb) returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(x),'[]')from(select pr.id,pr.display_name,pr.designation,pr.subjects,pr.classes,pr.approved_fields,pr.published_at from public.teacher_profiles pr where private.profile_visible(pr.id) and (coalesce(p->>'q','')=''or pr.display_name ilike '%'||replace(replace(p->>'q','%','\%'),'_','\_')||'%')and(coalesce(p->>'subject','')=''or p->>'subject'=any(pr.subjects))order by lower(pr.display_name),pr.id limit least(coalesce((p->>'limit')::int,25),100) offset greatest(coalesce((p->>'offset')::int,0),0))x$$;
create function public.student_progress(p jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$declare u uuid:=coalesce((p->>'studentId')::uuid,auth.uid());r jsonb;begin perform private.learning_access();if u<>auth.uid() and not private.student_access(u)then raise exception 'FORBIDDEN' using errcode='42501';end if;select jsonb_build_object('count',count(*),'earned',sum(total),'maximum',sum(maximum),'percentage',100.0*sum(total)/nullif(sum(maximum),0),'results',coalesce(jsonb_agg(jsonb_build_object('id',rr.id,'versionId',rr.version_id,'subject',e.subject,'total',rr.total,'maximum',rr.maximum,'scores',rr.scores,'revision',rr.revision,'publishedAt',rr.published_at)),'[]'),'generatedAt',now())into r from public.results rr join public.exam_versions e on e.id=rr.version_id where rr.student_id=u and rr.school_id=private.school() and private.report_result(rr.version_id,u) and (p->>'subject' is null or e.subject=p->>'subject')and(p->>'from' is null or rr.published_at>=(p->>'from')::timestamptz)and(p->>'to' is null or rr.published_at<(p->>'to')::timestamptz);return r;end$$;
